const $=s=>document.querySelector(s);const presets=EmberCatalog.presets;
let state={...presets[0],mode:'continuous',glow:true,trail:true},particles=[],playing=true,elapsed=0,last=0,spawnBudget=0,grid=true,light=false,filter='all';let savedData;try{savedData=JSON.parse(localStorage.getItem('ember-project'));if(savedData&&presets.some(p=>p.id===savedData.effect?.id)){state={...state,...savedData.effect};$('#name').value=savedData.name||'Untitled effect'}}catch{}
const definitions=[['amount','Particle amount',5,200,'A few','A lot'],['size','Particle size',1,30,'Small','Large'],['speed','Movement speed',1,100,'Drift','Rush'],['spread','Spread',5,100,'Focused','Wide'],['life','Lifetime',1,8,'Short','Long']];
function list(){const q=$('#search').value.toLowerCase();$('#presets').innerHTML=presets.filter(p=>(filter==='all'||p.group===filter)&&p.name.toLowerCase().includes(q)).map(p=>`<div class="preset-card"><button class="preset ${state.id===p.id?'active':''}" data-id="${p.id}" aria-pressed="${state.id===p.id}" title="Use on selected layer"><span class="thumb" style="--c:${p.color}">${p.symbol}</span><span><b>${p.name}</b><small>${p.tag}</small></span><span class="arrow">${state.id===p.id?'✓':''}</span></button><button class="preset-add" data-id="${p.id}" aria-label="Add ${p.name} to effect" title="Add as a new particle layer" ${window.emberCanAddLayer?.()===false?'disabled':''}>＋ Add to effect</button></div>`).join('')||'<p>No effects found. Try another search.</p>';document.querySelectorAll('.preset').forEach(b=>b.onclick=()=>{state={...presets.find(p=>p.id===b.dataset.id)};resetEmitter();sync();persist()});document.querySelectorAll('.preset-add').forEach(b=>b.onclick=()=>window.emberAddPresetLayer(b.dataset.id));}
function sync(){$('#effect-title').textContent=state.name+' ✦';$('#color').value=state.color;$('#mode').value=state.mode;$('#glow').checked=state.glow;$('#trail').checked=state.trail;$('#controls').innerHTML=definitions.map(([key,name,min,max,a,b])=>`<label class="control"><span class="label-row"><span>${name}</span><output id="value-${key}">${state[key]}${key==='life'?' s':''}</output></span><input type="range" min="${min}" max="${max}" value="${state[key]}" data-key="${key}" aria-label="${name}"><small><span>${a}</span><span>${b}</span></small></label>`).join('');document.querySelectorAll('[data-key]').forEach(el=>el.oninput=()=>{state[el.dataset.key]=+el.value;$('#value-'+el.dataset.key).textContent=el.value+(el.dataset.key==='life'?' s':'');persist()});document.querySelectorAll('[data-color]').forEach(b=>b.classList.toggle('chosen',b.dataset.color===state.color));list()}
let saveTimer;function persist(){try{localStorage.setItem('ember-project',JSON.stringify({name:$('#name').value,effect:state}));$('#saved').textContent='All changes saved'}catch{$('#saved').textContent='Local storage unavailable'}clearTimeout(saveTimer)}function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2500)}function restart(){particles=[];elapsed=0;spawnBudget=0;if(state.mode==='burst')for(let i=0;i<state.amount*2;i++)spawn()}
$('#search').oninput=list;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));list()});document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{state.color=b.dataset.color;sync();persist()});$('#color').oninput=e=>{state.color=e.target.value;document.querySelectorAll('[data-color]').forEach(b=>b.classList.toggle('chosen',b.dataset.color===state.color));persist()};['mode','glow','trail'].forEach(k=>$('#'+k).onchange=e=>{state[k]=e.target.type==='checkbox'?e.target.checked:e.target.value;if(k==='mode')resetEmitter();if(k==='trail')sync();persist()});$('#name').oninput=persist;$('#save').onclick=()=>{persist();toast('Project saved on this device')};$('#reset').onclick=()=>{state={...presets.find(p=>p.id===state.id)};sync();resetEmitter();persist();toast('Preset restored')};$('#play').onclick=()=>{playing=!playing;$('#play').textContent=playing?'Ⅱ':'▶';$('#play').setAttribute('aria-label',playing?'Pause preview':'Play preview')};$('#restart').onclick=restart;$('#grid').onclick=()=>{grid=!grid;$('#grid').classList.toggle('selected',grid)};$('#background').onclick=()=>light=!light;
function download(blob,name){const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}function filename(){return ($('#name').value||'effect').replace(/[^a-z0-9_-]/gi,'-')}function snapshot(){canvas.toBlob(b=>{if(b)download(b,filename()+'.png')});toast('Preview image exported')}$('#snapshot').onclick=snapshot;
function dialog(html){$('#dialog-content').innerHTML=html;$('#dialog').showModal()}$('#close').onclick=()=>$('#dialog').close();$('#dialog').onclick=e=>{if(e.target===$('#dialog'))$('#dialog').close()};$('#help').onclick=()=>dialog('<div class="eyebrow">A LITTLE HELP</div><h2>From idea to effect.</h2><p><b>1. Pick a starting point.</b><br>Choose an effect on the left. Every preset is ready to play.</p><p><b>2. Make it yours.</b><br>Change the color and sliders on the right. The preview updates as you go.</p><p><b>3. Keep your creation.</b><br>Your project saves on this device. Export a JSON project or a preview image.</p><p>Drag the preview to orbit, scroll to zoom, and right-drag to pan. Use camera views to inspect your effect. Niagara export is available in the desktop app.</p><button id="import">Import an Ember project</button>');$('#dialog-content').addEventListener('click',e=>{if(e.target.id==='import')importProject();if(e.target.id==='json'){download(new Blob([JSON.stringify(window.emberProject?emberProject():{format:'ember-vfx',version:1,name:$('#name').value,effect:state},null,2)],{type:'application/json'}),filename()+'.ember.json');toast('Effect settings exported')}if(e.target.id==='png')snapshot()});$('#export').onclick=()=>dialog('<div class="eyebrow">READY TO GO</div><h2>Keep your creation.</h2><p>Export an editable Ember project, or save an image of the current preview.</p><button id="json" class="primary">↓ Effect settings (.json)</button><button id="png">↓ Preview image (.png)</button><p>Settings can be reopened in Ember from the quick guide. Unreal / Niagara export is not supported.</p>');
function importProject(){const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{if(!input.files?.length)return;try{if(input.files[0].size>8*1024*1024)throw Error('Project is too large');const data=JSON.parse(await input.files[0].text());EmberFormat.validateProject(data);emberLoadProject(data);if($('#dialog').open)$('#dialog').close();toast('Project imported')}catch(error){toast(error.message||'Invalid project file')}};input.click()}


const canvas=$('#canvas');let viewport;try{viewport=new EmberViewport(canvas);$('#renderer-status').textContent='3D · WebGL';}catch(error){$('#renderer-status').textContent='3D graphics unavailable';const message=document.createElement('div');message.className='graphics-error';message.textContent='Ember needs WebGL 2 to show 3D effects. Update your graphics driver and restart the app.';canvas.parentElement.appendChild(message);console.error(error);}
function spawn(){particles.push(EmberParticles.spawn(state));}
function frame(now){const dt=Math.min((now-last)/1000,.04)*(+$('#speed').value);last=now;if(playing&&!window.updateLayers){elapsed+=dt;if(state.mode==='continuous'){spawnBudget+=dt*state.amount;while(spawnBudget>=1){spawn();spawnBudget--;}}else if(elapsed>state.life+.5){restart();}particles=particles.filter(p=>EmberParticles.step(p,dt,state));}const rendered=window.updateLayers?updateLayers(dt):particles;viewport?.render(rendered,state,grid,light);$('#particle-count').textContent=(window.updateLayers?rendered.length:particles.length)+' particles';if(!window.updateAnimationPlayhead)$('#time').textContent=elapsed.toFixed(2)+' s';if(playing&&window.updateLayers)elapsed+=dt;requestAnimationFrame(frame);}
$('#camera-view').onchange=e=>viewport?.view(e.target.value);$('#camera-reset').onclick=()=>{viewport?.home();$('#camera-view').value='perspective';};canvas.addEventListener('pointerdown',()=>$('#camera-view').value='perspective');canvas.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-','0'].includes(e.key)){e.preventDefault();if(!viewport)return;const offset=viewport.camera.position.clone().sub(viewport.controls.target);if(e.key==='0')viewport.home();else if(e.key==='+'||e.key==='='||e.key==='-'){offset.multiplyScalar(e.key==='-'?1.1:.9);offset.clampLength(70,1500);viewport.camera.position.copy(viewport.controls.target).add(offset);}else{const axis=new Ember3D.Vector3(0,0,1);if(e.key==='ArrowUp'||e.key==='ArrowDown')axis.copy(offset).cross(viewport.camera.up).normalize();offset.applyAxisAngle(axis,(e.key==='ArrowLeft'||e.key==='ArrowUp'?1:-1)*.12);viewport.camera.position.copy(viewport.controls.target).add(offset);}viewport.controls.update();}});
sync();restart();requestAnimationFrame(frame);

function resetEmitter(){if(window.resetSelectedLayer)resetSelectedLayer();else restart();}
